"header": "Join",
"sticky": false,
"html": "<input id=\"gameURL\" type=\"text\" placeholder=\"Enter Game URL/Code\" class=\"accountInput\" style=\"margin-top:0\" value=\"\"><div class=\"accountButton\" onclick=\"joinGame()\" style=\"width:100%\">Join</div>"
