"21": {
"header": "Advertise",
"sticky": false,
"html": "<div class=\"setHed\" style=\"margin-top:0;margin-bottom:10px\">Advertise in Game</div><div style=\"color:rgba(0,0,0,0.4)\">You have the ability to place custom text on Billboards in game. The text with the highest bid will be seen by all Krunker Players for 2 hours.<div style=\"height:10px\"></div></div><img src=\"img/ad_2.png\" style=\"width:100%;margin-top:10px;margin-bottom:10px\"><img id=\"bidPrevBB\" src=\"\"><div style=\"color:rgba(0,0,0,0.3)\">Please <a href=\"javascript:;\" onclick=\"showWindow(5);\" class=\"menuLink\">Login</a> to Submit a Bid.</div>"
},
"29": {
"header": "Support",
"sticky": false,
"html": "<div style=\"color:rgba(0,0,0,0.4);margin-top:0px\">To <b>Recover your Account</b> Contact us on <a>recovery@yendis.ch</a> Recovery is only possible if certain information can be provided.<div style=\"height:10px\"></div> <div style=\"color:rgba(0,0,0,0.4);margin-top:10px\">Contact us on <a>krunker@yendis.ch</a> for support requests relating to <b>Payments or Accounts</b>.<div style=\"height:25px\"></div> For <b>Bug Reports, Suggestions</b> or <b>Other Queries</b> join our <a href=\"#\" data-ext-href=\"https://discord.gg/Dw8F62u\">Discord</a> or <a href=\"#\" data-ext-href=\"https://www.reddit.com/r/KrunkerIO\">Reddit</a> communities.<div style=\"height:15px\"></div><div style=\"color:rgba(0,0,0,0.5)\"><b>Product &amp; Property of</b><br>Yendis AG Switzerland CHE-364.191.430<br>Yendis Entertainment AU Pty Ltd<br>Yendis Inc. CA<br></div><br>For Legal matters contact legal@yendis.ch </div></div>"
},
