"head": "<div class=\"settingsHeader\">\n            <div style=\"display:inline-block;text-align:right;float:right;\">\n                <div class=\"settingsBtn\" onclick=\"resetSettings()\">Reset</div>\n                <div class=\"settingsBtn\" onclick=\"exportSettings()\">Export</div>\n                <div class=\"settingsBtn\" onclick=\"importSettings()\">Import</div>\n                <select id=\"settingsPreset\" onchange=\"selectSettingPre(this.value)\" class=\"inputGrey2\" style=\"margin-left:0px;font-size:14px\">\n                    <option value=\"0\">Default</option>\n                    <option value=\"1\">Pro</option>\n                    <option value=\"3\">Performance</option>\n                    <option value=\"2\" selected=\"\">Custom</option>\n                </select>\n            </div>\n            <div style=\"display:inline-block;width:220px;\">\n                <input id=\"settSearch\" type=\"text\" placeholder=\"Search\" oninput=\"windows[0].searchList()\">\n            </div>\n            <div id=\"settingsTabLayout\"><div class=\"settingTab \" onclick=\"window.windows[0].changeTab(0)\">General</div>\n<div class=\"settingTab \" onclick=\"window.windows[0].changeTab(1)\">Controls</div>\n<div class=\"settingTab \" onclick=\"window.windows[0].changeTab(2)\">Display</div>\n<div class=\"settingTab \" onclick=\"window.windows[0].changeTab(3)\">Render</div>\n<div class=\"settingTab \" onclick=\"window.windows[0].changeTab(4)\">Game</div>\n<div class=\"settingTab \" onclick=\"window.windows[0].changeTab(5)\">Sound</div></div>\n        </div>",
